<template><div class="joint-controls" data-testid="joint-controls"><div v-if="!movable.length" class="dock-empty">没有可运动关节</div><div v-for="joint in movable" :key="joint.id" class="joint-row"><span>{{joint.name}}</span><el-slider :model-value="joint.value" :min="joint.limit.lower ?? -3.14" :max="joint.limit.upper ?? 3.14" :step="0.01" @input="move(joint.name, $event)"/><b>{{joint.value.toFixed(2)}}</b></div></div></template>
<script setup lang="ts">import {computed} from 'vue';import {useEditorStore} from '@/stores/editor';const store=useEditorStore();const movable=computed(()=>store.scene.joints.filter(x=>x.type!=='fixed'));function move(name:string,value:number|number[]){return store.moveJoint(name,Number(value))}</script>
